local AL={En=false,Sv={},Tx={},Ef={},Li={},Sh=nil,Q=nil}
local function isChar(i) local p=i while p and p~=Workspace do if p:IsA("Model") and p:FindFirstChildOfClass("Humanoid") then return true end p=p.Parent end return false end
local function togLag() if AL.En then AL.En=false for o,d in pairs(AL.Sv) do if typeof(o)=="Instance" and o.Parent then pcall(function() o.Color=d.Color o.Material=d.Material o.Reflectance=d.Reflectance end) end end for o,p in pairs(AL.Tx) do if typeof(o)=="Instance" and p then pcall(function() o.Parent=p end) end end for o,e in pairs(AL.Ef) do if typeof(o)=="Instance" and o.Parent then pcall(function() o.Enabled=e end) end end for o,p in pairs(AL.Li) do if typeof(o)=="Instance" and p then pcall(function() o.Parent=p end) end end if AL.Sh~=nil then Lighting.GlobalShadows=AL.Sh end if AL.Q and settings then pcall(function() settings().Rendering.QualityLevel=AL.Q end) end AL.Sv={} AL.Tx={} AL.Ef={} AL.Li={} else AL.En=true if settings then local ok,q=pcall(function() return settings().Rendering.QualityLevel end) if ok then AL.Q=q end pcall(function() settings().Rendering.QualityLevel=1 end) end for _,o in ipairs(Workspace:GetDescendants()) do if not isChar(o) then if o:IsA("Texture") or o:IsA("Decal") or o:IsA("SurfaceAppearance") then AL.Tx[o]=o.Parent o.Parent=nil elseif o:IsA("BasePart") and not o:IsA("Terrain") and not o:IsA("SpawnLocation") then AL.Sv[o]={Color=o.Color,Material=o.Material,Reflectance=o.Reflectance} o.Color=Color3.fromRGB(90,60,130) o.Material=Enum.Material.SmoothPlastic o.Reflectance=0 elseif o:IsA("ParticleEmitter") or o:IsA("Trail") or o:IsA("Beam") or o:IsA("Fire") or o:IsA("Smoke") or o:IsA("Sparkles") then AL.Ef[o]=o.Enabled o.Enabled=false end end end for _,c in ipairs(Lighting:GetChildren()) do if c:IsA("BlurEffect") or c:IsA("BloomEffect") or c:IsA("DepthOfFieldEffect") or c:IsA("SunRaysEffect") or c:IsA("ColorCorrectionEffect") or c:IsA("Atmosphere") or c:IsA("Sky") then AL.Li[c]=c.Parent c.Parent=nil end end AL.Sh=Lighting.GlobalShadows Lighting.GlobalShadows=false end end
local function getMx() return St.Lim and MAX_L or MAX_N end
local function appSpd() local c=LP.Character local h=c and c:FindFirstChildOfClass("Humanoid") if h then h.WalkSpeed=St.Spd and math.min(St.SV,CAP) or 16 end end
local function updSpdL() lSpd.Text=string.format("Speed: %d / %d",St.SV,getMx()) end updSpdL()
local function getP() local mc=LP.Character if not mc then return nil end local mr=mc:FindFirstChild("HumanoidRootPart") if not mr then return nil end local mp,sc=mr.Position,Camera.ViewportSize/2 local bt,bd=nil,math.huge for _,p in ipairs(Players:GetPlayers()) do if p~=LP then local c=p.Character if c then local h,hu=c:FindFirstChild("Head"),c:FindFirstChildOfClass("Humanoid") if h and hu and hu.Health>0 then local sp,os=Camera:WorldToViewportPoint(h.Position) if os then local d2=math.sqrt((sp.X-sc.X)^2+(sp.Y-sc.Y)^2) if not St.Fov or d2<=St.FR then local d3=(h.Position-mp).Magnitude if d3<bd then bd,bt=d3,h end end end end end end end return bt end
local function getN() local mc=LP.Character if not mc then return nil end local mr=mc:FindFirstChild("HumanoidRootPart") if not mr then return nil end local mp,sc=mr.Position,Camera.ViewportSize/2 local bt,bd=nil,math.huge for _,o in ipairs(Workspace:GetDescendants()) do if o:IsA("Model") and Players:GetPlayerFromCharacter(o)==nil then local h,hu=o:FindFirstChild("Head"),o:FindFirstChildOfClass("Humanoid") if h and hu and hu.Health>0 then local sp,os=Camera:WorldToViewportPoint(h.Position) if os then local d2=math.sqrt((sp.X-sc.X)^2+(sp.Y-sc.Y)^2) if not St.Fov or d2<=St.FR then local d3=(h.Position-mp).Magnitude if d3<bd then bd,bt=d3,h end end end end end end return bt end
bAim.MouseButton1Click:Connect(function() St.Aim=not St.Aim if not St.Aim and not St.Npc then St.Fov=false setB(bFov,false,"FOV ON","FOV OFF") end setB(bAim,St.Aim,"AIMBOT ON","AIMBOT OFF") updFov() end)
