bFov.MouseButton1Click:Connect(function() if not St.Aim and not St.Npc then return end St.Fov=not St.Fov setB(bFov,St.Fov,"FOV ON","FOV OFF") updFov() end)
bEsp.MouseButton1Click:Connect(function() St.Esp=not St.Esp setB(bEsp,St.Esp,"ESP ON","ESP OFF") if not St.Esp then for _,o in pairs(St.EspO) do if o.b then o.b:Destroy() end if o.h then o.h:Destroy() end if o.d then o.d:Destroy() end end St.EspO={} end end)
bSpd.MouseButton1Click:Connect(function() St.Spd=not St.Spd setB(bSpd,St.Spd,"SPEED ON","SPEED OFF") appSpd() end)
bLim.MouseButton1Click:Connect(function() St.Lim=not St.Lim setB(bLim,St.Lim,"LIMIT BREAK ON","LIMIT BREAK OFF") if not St.Lim and St.SV>getMx() then St.SV=getMx() end updSpdL() appSpd() end)
bLag.MouseButton1Click:Connect(function() pcall(togLag) setB(bLag,AL.En,"ANTI-LAG ON","ANTI-LAG OFF") end)
bMin.MouseButton1Click:Connect(function() St.FR=math.max(20,St.FR-10) updFov() end) bPlu.MouseButton1Click:Connect(function() St.FR=math.min(400,St.FR+10) updFov() end)
sMin.MouseButton1Click:Connect(function() St.SV=math.max(1,St.SV-1) updSpdL() appSpd() end) sPlu.MouseButton1Click:Connect(function() if St.SV<getMx() then St.SV=St.SV+1 updSpdL() appSpd() end end)
RunService.RenderStepped:Connect(function()
if fovC.Visible then fovC.Position=UDim2.new(0.5,-St.FR,0.5,-St.FR) end
if St.Aim then local h=getP() if h then Camera.CFrame=CFrame.new(Camera.CFrame.Position,h.Position) end end
if St.Npc then local h=getN() if h then Camera.CFrame=CFrame.new(Camera.CFrame.Position,h.Position) end end
if St.Spd then local c=LP.Character local h=c and c:FindFirstChildOfClass("Humanoid") if h then local tg=math.min(St.SV,CAP) if h.WalkSpeed~=tg then h.WalkSpeed=tg end end end
e=false o.h.Visible=false o.d.Visible=false end else if o then o.b:Destroy() o.h:Destroy() o.d:Destroy() St.EspO[p]=nil end end end end end end)
